1:import type { ReactNode } from "react";
2:import { type Dict, t } from "../i18n/dictionaries";
3:import { failureTone, type FailureOutcome } from "@fbj/core";
4:
5:/**
6: * The failure, said in the reader's language, with the agent's own words kept.
7: *
8: * Two rules shape this component:
9: *
10: * - **the raw report never disappears.** It is the only thing that is certainly
11: *   true, it is what a support conversation needs, and for `unknown` it is the
12: *   entire answer. It moves behind a disclosure, it is not dropped.
13: * - **the summary never over-claims.** `failureCopy` has one entry per outcome
14: *   and no default that guesses: an unclassified report renders "the agent
15: *   stopped here" and shows the report, which is exactly what we know.
16: */
17:export function failureCopy(
18:  dict: Dict,
19:  outcome: FailureOutcome,
20:  platformLabel?: string | null,
21:): { title: string; body: string } {
22:  const f = dict.failure;
23:  switch (outcome) {
24:    case "needs_login":
25:      return platformLabel
26:        ? {
27:            title: t(f.needsLoginTitle, { platform: platformLabel }),
28:            body: t(f.needsLoginBody, { platform: platformLabel }),
29:          }
30:        : {
31:            title: f.needsLoginTitleGeneric,
32:            body: f.needsLoginBodyGeneric,
33:          };
34:    case "needs_answer":
35:      return { title: f.needsAnswerTitle, body: f.needsAnswerBody };
36:    case "posting_gone":
37:      return { title: f.postingGoneTitle, body: f.postingGoneBody };
38:    case "wall":
39:      return { title: f.wallTitle, body: f.wallBody };
40:    case "our_bug":
41:      return { title: f.ourBugTitle, body: f.ourBugBody };
42:    case "unknown":
43:      return { title: f.unknownTitle, body: f.unknownBody };
44:  }
45:}
46:
47:/**
48: * `card` is the job page's failure panel; `cell` is the compact form for a row
49: * in the applications table, where the headline and the disclosure are all
50: * there is room for and the explanation lives one click away on the job page.
51: */
52:export function FailureSummary({
53:  dict,
54:  outcome,
55:  reason,
56:  platformLabel,
57:  variant = "card",
58:  children,
59:}: {
60:  dict: Dict;
61:  outcome: FailureOutcome;
62:  reason: string | null;
63:  platformLabel?: string | null;
64:  variant?: "card" | "cell";
65:  /** Actions rendered under the explanation (the login CTA, Q&A, retry). */
66:  children?: ReactNode;
67:}) {
68:  const { title, body } = failureCopy(dict, outcome, platformLabel);
69:  const details = reason?.trim() ? (
70:    <details className="fail-details">
71:      <summary>{dict.failure.detailsToggle}</summary>
72:      <span className="fail-raw">{reason}</span>
73:    </details>
74:  ) : null;
75:
76:  if (variant === "cell") {
77:    return (
78:      <div className="fail-cell">
79:        <span className={`fail-headline tone-${failureTone(outcome)}`}>
80:          {title}
81:        </span>
82:        {details}
83:      </div>
84:    );
85:  }
86:
87:  return (
88:    <section className={`fail ${failureTone(outcome)}`}>
89:      <span className="fail-kicker">{dict.failure.title}</span>
90:      <p className="fail-headline">{title}</p>
91:      <p className="fail-body">{body}</p>
92:      {children ? <div className="fail-actions">{children}</div> : null}
93:      {details}
94:    </section>
95:  );
96:}
